x);box-shadow:0 2px 0 #8e3d2c}.title-foot{font-size:9px;color:#767d76;margin-top:37px}.title-foot span{color:#fa754d;padding:0 8px}.title-version{position:absolute;bottom:22px;left:28px;font-size:9px;color:#727a73}.title-noise,.title-scan{position:absolute;inset:0;pointer-events:none;opacity:.16;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.8' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.32'/%3E%3C/svg%3E")}.title-monster{position:absolute;right:5%;top:12%;width:min(33vw,390px);height:80%;opacity:.85;filter:drop-shadow(0 20px 20px #0009);transform:rotate(7deg)}.monster-head{position:absolute;top:3%;left:18%;width:67%;height:35%;background:linear-gradient(125deg,#267f6e,#175347 75%);border-radius:48% 48% 46% 46%;z-index:2;box-shadow:inset -17px -14px #0f3f37}.ear{position:absolute;top:-19%;width:23%;height:48%;background:#206b5a;border-radius:60% 55% 20% 20%;transform:rotate(-20deg)}.e1{left:10%}.e2{right:7%;transform:rotate(25deg)}.monster-face{position:absolute;inset:24% 14% 12%;background:#247a67;border-radius:50%}.eye{position:absolute;top:27%;width:13%;height:18%;border-radius:50%;background:#e8dfb9;box-shadow:0 0 12px #fff5}.eye:after{content:'';position:absolute;inset:25%;background:#16191a;border-radius:50%}.eye.one{left:26%}.eye.two{right:26%}.smile{position:absolute;bottom:11%;left:22%;width:56%;height:20%;border-bottom:5px solid #f3dac0;border-radius:0 0 50% 50%}.monster-body{position:absolute;top:35%;left:24%;width:58%;height:56%;background:linear-gradient(90deg,#174a40,#2b806b,#123d35);border-radius:45% 45% 20% 20%;transform:skew(-4deg);box-shadow:inset -22px 0 #10382f}.monster-shadow{position:absolute;bottom:3%;left:10%;width:90%;height:16%;background:#0008;filter:blur(20px);border-radius:50%}.title-screen:after{content:''}.screen:not(.overlay){background:radial-gradient(ellipse at 38% 44%,#39443f 0,#202a28 33%,#111819 78%)}.screen:not(.overlay):before{content:'';position:absolute;inset:0;background:linear-gradient(90deg,#0d1315dd 0%,#101617aa 42%,#0d131500 74%),repeating-linear-gradient(0deg,transparent 0 68px,#ffffff06 69px 70px);pointer-events:none}.title-scan{opacity:.08;z-index:4}.overlay{background:#080c0de8;z-index:10}.dialog{text-align:center;width:min(90vw,480px);padding:45px 28px;border:1px solid #464a41;background:linear-gradient(140deg,#1d2725,#121a1b);box-shadow:0 20px 80px #0009}.dialog h2{font:800 clamp(36px,7vw,57px)/.95 'Barlow Condensed',sans-serif;color:#f2dec0;margin:20px 0 12px}.dialog p{color:#a7aaa0;font-size:14px}.dialog .start-btn{margin-top:24px}
#hud{position:absolute;inset:0;pointer-events:none}.topbar{position:absolute;top:0;left:0;right:0;height:67px;padding:0 25px;display:flex;align-items:center;justify-content:space-between;background:linear-gradient(#0b1010db,#0b101070,transparent);pointer-events:auto}.brand{display:flex;align-items:center;gap:10px;font:800 16px 'Barlow Condensed',sans-serif;letter-spacing:.1em;color:#f1ddba}.brand-mark{display:grid;place-items:center;width:30px;height:30px;background:#f06b41;color:white;border-radius:50%;font:900 20px 'Barlow Condensed',sans-serif}.brand-lite{color:#cf7050}.brand small{display:block;color:#a6a99d;font:9px 'DM Mono',monospace;letter-spacing:.2em;margin-top:2px}.chapter{font-size:9px;color:#a8a99d}.chapter b{color:#ed7149;padding:0 4px}.icon-btn{width:34px;height:34px;border:1px solid #77796d;background:#131a1bd9;color:#eee2c9;font-size:15px;cursor:pointer}.mission{position:absolute;left:25px;top:88px;padding:14px 18px;width:250px;background:#111917d9;border-left:3px solid #f0784d;box-shadow:0 5px 20px #0003}.mission-label{font-size:8px;color:#a4a69b}.mission #objective{font-size:14px;font-weight:700;margin-top:6px;color:#f1e7d3}.steps{display:flex;gap:5px;margin-top:12px}.steps i{height:3px;flex:1;background:#424a43}.steps i.done{background:#72dbc3;box-shadow:0 0 7px #72dbc366}.hint{position:absolute;left:50%;bottom:96px;transform:translateX(-50%);white-space:nowrap;padding:9px 14px;background:#111a19e6;border:1px solid #697064;color:#eee4cf;font:11px 'DM Mono',monospace;letter-spacing:.04em;opacity:0;transition:opacity .15s}.hint.show{opacity:1}.bottom-ui{position:absolute;left:25px;right:25px;bottom:22px;display:flex;align-items:end;justify-content:space-between}.glove-card{display:flex;align-items:center;gap:10px;padding:9px 13px;background:#111917e8;border:1px solid #50584f;min-width:185px}.glove-icon{width:34px;height:34px;border-radius:50%;display:grid;place-items:center;color:#73ddd0;font-size:21px;background:#294743}.glove-card b{display:block;font:800 12px 'Barlow Condensed',sans-serif;letter-spacing:.1em}.glove-card small{display:block;font-size:8px;color:#f17a4f;margin-top:3px}.charge{display:flex;gap:3px;margin-left:auto}.charge i{width:5px;height:18px;background:#343d38}.charge i.on{background:#74dfca;box-shadow:0 0 8px #74dfca77}.controls-tip{font-size:8px;color:#bdc0b5;letter-spacing:.07em;padding:9px 12px;background:#111917c9}.controls-tip span{color:#ef7950;padding:0 7px}kbd{font:9px 'DM Mono',monospace;color:#f3e7d0;border:1px solid #72766d;padding:3px 4px;margin-right:4px}.vignette{position:absolute;inset:0;pointer-events:none;box-shadow:inset 0 0 100px 25px #0009}.topbar,.mission,.bottom-ui,.hint{z-index:2}.vignette{z-index:1}#mobile-controls{display:none;pointer-events:auto;position:absolute;bottom:18px;right:20px;z-index:3}.pad button,#mobile-action{width:42px;height:42px;border-radius:9px;border:1px solid #9fa19770;background:#18211fdc;color:#f3ead7;font-size:17px;touch-action:none}.pad>div{display:flex;gap:4px}.pad>button{margin:0 0 4px 47px}.pad{opacity:.8}.pad button:active,#mobile-action:active{background:#ef7048}.pad{display:flex;flex-direction:column}.pad>div button{margin:0}#mobile-action{height:50px;width:68px;margin-left:12px;font:800 11px 'Barlow Condensed',sans-serif;letter-spacing:.1em;background:#ef7048}.screen.overlay{pointer-events:auto}
@media(max-width:700px){.title-monster{right:-10%;width:54vw;opacity:.55}.title-content{margin-top:0}.logo-top{font-size:clamp(70px,17vw,112px)}.logo-bottom{font-size:clamp(46px,12vw,76px)}.subtitle{font-size:10px;letter-spacing:.3em}.title-foot{font-size:7px}.chapter{display:none}.mission{top:77px;left:12px;width:205px;padding:11px 13px}.topbar{height:56px;padding:0 13px}.bottom-ui{left:12px;right:12px;bottom:12px}.controls-tip{display:none}.glove-card{min-width:165px}.hint{bottom:111px;font-size:9px;max-width:90vw;white-space:normal;text-align:center}.vignette{box-shadow:inset 0 0 55px 10px #0008}#mobile-controls{display:flex;align-items:end}.glove-card{padding:7px 9px}.title-version{bottom:9px;left:12px;font-size:7px}}
@media(max-height:500px) and (orientation:landscape){.title-content{margin:0}.logo{margin:13px 0}.logo-top{font-size:72px}.logo-bottom{font-size:50px}.subtitle{margin:13px 0}.title-foot{margin-top:16px}.start-btn{margin-top:16px;padding:10px 24px}.title-monster{top:3%;height:90%}}

(() => {
  'use strict';
  const canvas = document.getElementById('game'), ctx = canvas.getContext('2d');
  const hud = document.getElementById('hud'), title = document.getElementById('title-screen');
  const pauseScreen = document.getElementById('pause-screen'), endScreen = document.getElementById('end-screen');
  const objective = document.getElementById('objective'), hint = document.getElementById('hint');
  const W = 1940, H = 1420, TILE = 80;
  let vw = innerWidth, vh = innerHeight, dpr = 1, started = false, paused = false, ended = false, last = 0;
  let cam = {x:0,y:0}, time = 0, handFlash = 0, stunTime = 0, cooldown = 0, hintTarget = null;
  const keys = new Set(), held = new Set();
  const player = {x:150,y:1160,r:17,dx:0,dy:-1,speed:210,glove:false,alive:true};
  const fuses = [
    {x:390,y:1060,color:'#4fc6f0',name:'FROST CELL',taken:false},
    {x:930,y:320,color:'#f2bf4d',name:'SUN CELL',taken:false},
    {x:1530,y:1130,color:'#d77bf2',name:'VIOLET CELL',taken:false}
  ];
  const panel={x:930,y:1120};
  const gloveItem={x:260,y:1160,taken:false};
  const exit={x:1710,y:230};
  const walls=[
    {x:0,y:0,w:W,h:38},{x:0,y:H-38,w:W,h:38},{x:0,y:0,w:38,h:H},{x:W-38,y:0,w:38,h:H},
    {x:620,y:38,w:42,h:800},{x:620,y:1040,w:42,h:342},
    {x:38,y:620,w:740,h:40},{x:1000,y:620,w:390,h:40},{x:1590,y:620,w:312,h:40},
    {x:1260,y:660,w:42,h:180},{x:1260,y:1060,w:42,h:322},
    {x:305,y:345,w:155,h:36},{x:760,y:900,w:120,h:38},{x:1470,y:340,w:175,h:38},
    {x:1040,y:1280,w:170,h:38}
  ];
  const crates=[{x:160,y:820,w:80,h:70},{x:420,y:795,w:90,h:70},{x:770,y:1125,w:82,h:78},{x:1040,y:870,w:90,h:80},{x:1450,y:930,w:92,h:82},{x:1710,y:440,w:92,h:76},{x:810,y:250,w:100,h:62},{x:360,y:465,w:76,h:92}];
  const enemy={x:930,y:245,r:27,active:false,stunned:0,path:[],pathAt:0,pathTick:0,anim:0};
  const totalFuses=()=>fuses.filter(f=>f.taken).length;
  function resize(){vw=innerWidth;vh=innerHeight;dpr=Math.min(devicePixelRatio||1,1.8);canvas.width=Math.round(vw*dpr);canvas.height=Math.round(vh*dpr);ctx.setTransform(dpr,0,0,dpr,0,0)}
  addEventListener('resize',resize);resize();
  function reset(){player.x=150;player.y=1160;player.glove=false;fuses.forEach(f=>f.taken=false);gloveItem.taken=false;enemy.x=930;enemy.y=245;enemy.active=false;enemy.stunned=0;enemy.path=[];time=0;ended=false;paused=false;cooldown=0;stunTime=0;endScreen.classList.add('hidden');pauseScreen.classList.add('hidden');updateHud()}
  function begin(){reset();started=true;title.classList.add('hidden');hud.classList.remove('hidden')}
  document.getElementById('start-btn').addEventListener('click',begin);
  document.getElementById('again-btn').addEventListener('click',()=>{begin()});
  document.getElementById('pause-btn').addEventListener('click',togglePause);
  document.getElementById('resume-btn').addEventListener('click',togglePause);
  function togglePause(){if(!started||ended)return;paused=!paused;pauseScreen.classList.toggle('hidden',!paused)}
  addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();keys.add(k);if(k==='escape'||k==='p')togglePause();if(k==='e'&&!e.repeat)interact()});
  addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
  document.querySelectorAll('[data-dir]').forEach(b=>{const k={up:'w',down:'s',left:'a',right:'d'}[b.dataset.dir];b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);held.add(k)});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>b.addEventListener(ev,()=>held.delete(k)))});
  document.getElementById('mobile-action').addEventListener('pointerdown',e=>{e.preventDefault();fireHand()});
  canvas.addEventListener('pointerdown',e=>{if(started&&!paused&&!ended){fireHand(e.clientX,e.clientY)}});
  function dist(a,b){return Math.hypot(a.x-b.x,a.y-b.y)}
  function nearestThing(){let out=null,best=Infinity;const things=[];if(!gloveItem.taken)things.push({type:'glove',...gloveItem});fuses.filter(f=>!f.taken).forEach(f=>things.push({type:'fuse',...f}));things.push({type:'panel',...panel});if(enemy.active)things.push({type:'enemy',...enemy});if(!enemy.active||totalFuses()<3)things.push({type:'exit',...exit});for(const t of things){const d=dist(player,t);if(d<best){best=d;out=t}}return out?{...out,d:best}:null}
  function interact(){if(!started||paused||ended)return;const t=nearestThing();if(!t||t.d>72)return;useThing(t)}
  function useThing(t){if(t.type==='glove'&&!gloveItem.taken){gloveItem.taken=true;player.glove=true;ping(480);message('GRABGLOVE ONLINE. Aim and click to pull things close.');updateHud();return}
    if(t.type==='fuse'&&!t.taken){const f=fuses.find(q=>q.name===t.name);if(f){f.taken=true;ping(620);updateHud();message(`${f.name} secured.`)}return}
    if(t.type==='panel'){if(!player.glove){message('The power panel is dead. Find the GrabGlove first.');return}if(totalFuses()<3){message(`Power panel: ${totalFuses()}/3 cells installed.`);return}if(!enemy.active){enemy.active=true;enemy.x=930;enemy.y=245;ping(250);message('POWER RESTORED. Something woke up in the dark. RUN TO THE EXIT!');updateHud()}return}
    if(t.type==='exit'&&enemy.active&&totalFuses()===3){win()}
  }
  function fireHand(px,py){if(!player.glove||cooldown>0)return;cooldown=0.55;handFlash=.24;const aimX=px==null?player.dx:px-vw/2+cam.x,aimY=py==null?player.dy:py-vh/2+cam.y;let ax,ay;if(px==null){ax=aimX;ay=aimY}else{ax=aimX-player.x;ay=aimY-player.y}const n=Math.hypot(ax,ay)||1;ax/=n;ay/=n;
    const candidates=[];if(!gloveItem.taken)candidates.push({type:'glove',...gloveItem});fuses.filter(f=>!f.taken).forEach(f=>candidates.push({type:'fuse',...f}));candidates.push({type:'panel',...panel});let best=null,bestAlong=Infinity;
    for(const t of candidates){const vx=t.x-player.x,vy=t.y-player.y,along=vx*ax+vy*ay,perp=Math.abs(vx*ay-vy*ax);if(along>0&&along<390&&perp<50&&along<bestAlong){best=t;bestAlong=along}}
    if(best){if(best.type==='glove'){gloveItem.taken=true;player.glove=true;ping(480);message('GRABGLOVE ONLINE. You can pull cells from a short distance.');updateHud()}else if(best.type==='fuse'){const f=fuses.find(q=>q.name===best.name);if(f){f.taken=true;ping(620);message(`${f.name} reeled in.`);updateHud()}}else if(best.type==='panel'){if(totalFuses()===3){useThing(best)}else message(`Panel needs 3 cells. ${totalFuses()}/3 found.`)}handFlash=.28;return}
    if(enemy.active&&dist(player,enemy)<310){const vx=enemy.x-player.x,vy=enemy.y-player.y,along=vx*ax+vy*ay,perp=Math.abs(vx*ay-vy*ax);if(along>0&&perp<70&&cooldown>.2){enemy.stunned=2.2;stunTime=2.2;ping(160);message('The GrabGlove bought you a few seconds. MOVE!');return}}
  }
  let messageTimer=0;function message(text){hint.textContent=text;hint.classList.add('show');messageTimer=3.1}
  function updateHud(){const f=totalFuses();let text;if(!player.glove)text='Find the GrabGlove';else if(f<3)text=`Find power cells · ${f} / 3`;else if(!enemy.active)text='Restore power at the main panel';else text='Run to the exit — NOW';objective.textContent=text;document.getElementById('glove-status').textContent=player.glove?(enemy.active?'CHARGED · RUN':'READY'):'OFFLINE';document.querySelectorAll('.steps i').forEach((el,i)=>el.classList.toggle('done',i<(player.glove?1:0)+f));document.querySelectorAll('.charge i').forEach((el,i)=>el.classList.toggle('on',i<f));}
  let audioCtx=null;function ping(freq){try{audioCtx=audioCtx||new (window.AudioContext||window.webkitAudioContext)();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(.055,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+.24);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+.25)}catch(_){}}
  function win(){ended=true;document.getElementById('end-eyebrow').textContent='SHIFT COMPLETE';document.getElementById('end-title').textContent='YOU MADE IT OUT.';document.getElementById('end-copy').textContent='Some toys are better left on the shelf.';endScreen.classList.remove('hidden');ping(740)}
  function caught(){player.x=150;player.y=1160;enemy.x=930;enemy.y=245;enemy.stunned=0;message('It caught you! The night guard dragged you back to the lobby.');}

input.newString:
function caught(){player.x=150;player.y=1160;enemy.x=930;enemy.y=245;enemy.stunned=0;enemy.path=[];message('It caught you! The night guard dragged you back to the lobby.');}
function blocked(x,y,r){for(const w of walls){if(x+r>w.x&&x-r<w.x+w.w&&y+r>w.y&&y-r<w.y+w.h)return true}for(const c of crates){if(x+r>c.x&&x-r<c.x+c.w&&y+r>c.y&&y-r<c.y+c.h)return true}return false}
function moveEntity(ent,dx,dy,r){if(!blocked(ent.x+dx,ent.y,r))ent.x+=dx;if(!blocked(ent.x,ent.y+dy,r))ent.y+=dy}
function gridPos(x,y){return [Math.floor(x/48),Math.floor(y/48)]}
function findPath(){const [sx,sy]=gridPos(enemy.x,enemy.y),[tx,ty]=gridPos(player.x,player.y),cols=Math.ceil(W/48),rows=Math.ceil(H/48),start=sy*cols+sx,target=ty*cols+tx;if(start===target)return[];const prev=new Int32Array(cols*rows);prev.fill(-2);prev[start]=-1;const q=[start],dirs=[1,0,-1,0,0,1,0,-1];let found=false;for(let i=0;i<q.length&&i<cols*rows;i++){const cur=q[i];if(cur===target){found=true;break}const x=cur%cols,y=Math.floor(cur/cols);for(let d=0;d<4;d++){const nx=x+dirs[d*2],ny=y+dirs[d*2+1];if(nx<0||ny<0||nx>=cols||ny>=rows)continue;const ni=ny*cols+nx;if(prev[ni]!==-2||blocked(nx*48+24,ny*48+24,enemy.r))continue;prev[ni]=cur;q.push(ni)}}if(!found)return[];const path=[];let at=target;while(at!==start&&at>=0){path.push({x:(at%cols)*48+24,y:Math.floor(at/cols)*48+24});at=prev[at]}return path.reverse()}
function update(dt){if(!started||paused||ended)return;time+=dt;cooldown=Math.max(0,cooldown-dt);handFlash=Math.max(0,handFlash-dt);stunTime=Math.max(0,stunTime-dt);if(messageTimer>0){messageTimer-=dt;if(messageTimer<=0)hint.classList.remove('show')}
  let x=(keys.has('d')||keys.has('arrowright')||held.has('d')?1:0)-(keys.has('a')||keys.has('arrowleft')||held.has('a')?1:0),y=(keys.has('s')||keys.has('arrowdown')||held.has('s')?1:0)-(keys.has('w')||keys.has('arrowup')||held.has('w')?1:0);const len=Math.hypot(x,y);if(len){x/=len;y/=len;player.dx=x;player.dy=y;const speed=player.speed*(enemy.active?.93:1);moveEntity(player,x*speed*dt,y*speed*dt,player.r)}
